
public class A1Q7 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println('A' + 1);
		System.out.println("A" + 1);
		System.out.println((char)('A' + 1));
		System.out.println('1' + 1);
		System.out.println("1" + 1);
		
		// 66 - ASCII value of A is 65
		// A1 - Simple concatenation
		// B - B's ASCII value is 67
		// 50 - Integer 1 ASCII value is 49
		// 11 - Simple concatenation
	}

}
